#pragma once
#include "rinkfit/joint_model.hpp"
#include <map>
#include <set>
#include <tuple>
namespace rinkfit {
template<class T>T joint_normalized_print_height_envelope_v1(const T*g,const T*q,const T*ad,const std::vector<int>&indices,int offset,bool upper){const T*a=ad+offset;T result=T(0);bool first=true;for(int index:indices){const T h=a[2]+(a[3]-a[2])*q[index],value=upper?h-g[4]:-h;if(first||event_scalar(value)>event_scalar(result)){result=value;first=false;}}if(first)throw std::runtime_error("empty normalized print height domain");return result;}
template<class T>T joint_normalized_print_course_span_v1(const T*g,const T*q,const T*ad,const std::vector<int>&indices,int offset){if(indices.empty())throw std::runtime_error("empty normalized print course domain");T lo=q[indices[0]],hi=lo;for(int index:indices){if(event_scalar(q[index])<event_scalar(lo))lo=q[index];if(event_scalar(q[index])>event_scalar(hi))hi=q[index];}const T per=T(2)*(T(1)-T(2)*g[1]+g[0]-T(2)*g[2])+T(4)*EventModel::quarter_arclength(T(1.5707963267948966),g);return ad[offset+1]*(hi-lo)-per;}
template<class T>T joint_normalized_print_envelope_bound_v1(const T*vertex,const T*envelope,int direction){return direction?vertex[0]-envelope[1]:envelope[0]-vertex[0];}
template<class T>T joint_normalized_print_envelope_span_v1(const T*g,const T*envelope,const T*ad,int offset){const T per=T(2)*(T(1)-T(2)*g[1]+g[0]-T(2)*g[2])+T(4)*EventModel::quarter_arclength(T(1.5707963267948966),g);return ad[offset+1]*(envelope[1]-envelope[0])-per;}
inline std::vector<EventPhysicalConstraint>joint_normalized_print_domain_specs_v1(const JointEventModel&m){
 std::map<std::tuple<int,int,int>,std::set<std::pair<int,int>>>coordinates;
 std::set<std::tuple<int,int,int>>split_heights,split_spans;std::set<std::pair<int,int>>split_courses;
 for(std::size_t mi=0;mi<m.materials.size();++mi)for(std::size_t pi=0;pi<m.materials[mi].paths.size();++pi){const auto&p=m.materials[mi].paths[pi];if(p.kind!=6||p.advertisement_block<0)continue;if(!p.vertex_blocks.empty()){if(p.course_envelope_block<0||m.blocks.at(p.course_envelope_block).values.size()!=2)throw std::runtime_error("split print requires a numeric course envelope");for(int vertex:p.vertex_blocks){if(m.blocks.at(vertex).values.size()!=2)throw std::runtime_error("split print vertex coordinate shape");split_heights.insert({vertex,p.advertisement_block,p.advertisement_offset});split_courses.insert({vertex,p.course_envelope_block});}split_spans.insert({p.course_envelope_block,p.advertisement_block,p.advertisement_offset});continue;}auto indices=m.path_geometry_indices.at({int(mi),int(pi)});if(indices.empty()){const auto n=m.blocks.at(p.geometry_block).values.size();for(std::size_t k=m.path_geometry_offsets.at({int(mi),int(pi)});k<n;++k)indices.push_back(int(k));}if(indices.empty()||indices.size()%2)throw std::runtime_error("normalized print physical coordinate shape");auto&selected=coordinates[{p.geometry_block,p.advertisement_block,p.advertisement_offset}];for(std::size_t k=0;k<indices.size();k+=2)selected.insert({indices[k],indices[k+1]});}
 std::vector<EventPhysicalConstraint>result;
 for(const auto&entry:coordinates){const auto bi=std::get<0>(entry.first),ai=std::get<1>(entry.first),off=std::get<2>(entry.first);const auto prefix=m.blocks.at(bi).name+"/installation_"+std::to_string(ai)+"_"+std::to_string(off);std::set<int>heights,courses;for(const auto&xy:entry.second){courses.insert(xy.first);heights.insert(xy.second);}for(int direction:{0,1}){EventPhysicalConstraint c;c.id=prefix+"/height_envelope/"+std::to_string(direction);c.type=19;c.axis=off;c.direction=direction;c.coordinate_indices.assign(heights.begin(),heights.end());c.block_ids={m.scene_block,bi,ai};result.push_back(std::move(c));}EventPhysicalConstraint c;c.id=prefix+"/finite_course_span";c.type=20;c.axis=off;c.block_ids={m.scene_block,bi,ai};c.coordinate_indices.assign(courses.begin(),courses.end());result.push_back(std::move(c));}
 for(const auto&entry:split_heights){const int vertex=std::get<0>(entry),ad=std::get<1>(entry),off=std::get<2>(entry);for(int direction:{0,1}){EventPhysicalConstraint c;c.id="normalized_print/v"+std::to_string(vertex)+"/a"+std::to_string(ad)+"/o"+std::to_string(off)+"/h"+std::to_string(direction);c.type=19;c.axis=off;c.direction=direction;c.coordinate_indices={1};c.block_ids={m.scene_block,vertex,ad};result.push_back(std::move(c));}}
 for(const auto&entry:split_courses)for(int direction:{0,1}){EventPhysicalConstraint c;c.id="normalized_print/v"+std::to_string(entry.first)+"/e"+std::to_string(entry.second)+"/u"+std::to_string(direction);c.type=21;c.direction=direction;c.block_ids={m.scene_block,entry.first,entry.second};result.push_back(std::move(c));}
 for(const auto&entry:split_spans){const int env=std::get<0>(entry),ad=std::get<1>(entry),off=std::get<2>(entry);EventPhysicalConstraint c;c.id="normalized_print/e"+std::to_string(env)+"/a"+std::to_string(ad)+"/o"+std::to_string(off)+"/span";c.type=22;c.axis=off;c.block_ids={m.scene_block,env,ad};result.push_back(std::move(c));}
 return result;
}
}
